function setFullContentMode(mode,{render=true}={}){const next=mode==='lyrics'?'lyrics':'queue',changed=fullContentMode!==next;fullContentMode=next;const queuePanel=$('fullQueuePanel'),lyricsSection=$('fullLyricsSection');if(queuePanel)queuePanel.hidden=next!=='queue';if(lyricsSection)lyricsSection.hidden=next!=='lyrics';for(const [id,value] of [['fullQueueTab','queue'],['fullTextTab','lyrics']]){const tab=$(id);if(tab){tab.classList.toggle('active',next===value);tab.setAttribute('aria-pressed',String(next===value));}}if(changed&&$('fullPanelBody'))VKSoundMotion.reveal($('fullPanelBody'));if(render){if(next==='lyrics'){const key=viewedTrackKey();if(key&&fx.lyricKey!==key)loadLyrics(key,fullFollow);}else renderFullQueue();}}
