 scroll.addEventListener('pointerdown',()=>{fullPointerBusy=true;clearTimeout(fullSnapTimer);});window.addEventListener('pointerup',()=>{fullPointerBusy=false;});
 $('fullPlayer').addEventListener('close',()=>{experience.queueSignature='';clearTimeout(fullSnapTimer);clearTimeout(wheelResetTimer);clearTimeout(wheelFeedbackTimer);wheelPull=0;resetWheelFeedback();fullSnapUntil=0;if(frame)cancelAnimationFrame(frame);frame=0;sticky.inert=true;sticky.setAttribute('aria-hidden','true');scroll.classList.remove('is-condensed');});
