// Shared cards: no nested buttons, all playback actions use the existing audio engine.
async function obtainList(p,source){const account=db.profile?.id,epoch=fx.epoch;if(source==='local')return p;let list=p;if(source==='remote'){if(!p.syncedAt){await syncAll('list',p.id);list=(db.vkLists||[]).find(x=>x.id===p.id)||p;}}else list=await call(source==='recommend'?'recommendationTracks':'catalogAlbum',{id:p.id});if(account!==db.profile?.id||epoch!==fx.epoch)throw Object.assign(Error('Аккаунт изменился.'),{code:'CANCELLED'});await snapshot();return list;}
async function playMediaList(p,source,random=false){const list=await obtainList(p,source);let keys=(list.keys||[]).filter(k=>canPlay(db.rows[k]));if(random)keys=shuffle(keys);if(!keys.length){toast('Нет доступных треков.',false,'info');return;}mixPlayback=false;const coverKey=p.coverKey||(list.keys||[]).map(k=>db.rows[k]?.coverKey).find(Boolean)||'';await playTrack(keys[0],keys,{mix:false,queueCoverKey:coverKey});}
function openMediaList(p,source){if(source==='local')go('pl:'+p.id);else if(source==='remote')go('vk:'+p.id);else if(source==='recommend')openRecommended(p.id);else openArtistAlbum(p.id);}
async function downloadMediaList(p,source){if(saveBusy||bulkBusy||remoteBusy){toast('Дождитесь текущей операции.',false,'info');return;}saveBusy=true;try{const list=await obtainList(p,source),accountId=db.profile?.id,keys=[...new Set(list.keys||[])].filter(k=>!isLocal(k)&&!isCached(k)),items=[];if(!keys.length){toast('Все доступные треки уже сохранены.',false,'info');return;}for(let i=0;i<keys.length;i+=100){if(accountId!==db.profile?.id)throw Object.assign(Error('Аккаунт изменился.'),{code:'CANCELLED'});const result=await call('cacheBatch',{op:'save',keys:keys.slice(i,i+100),accountId});if(result.cancelled)break;if(result.items)items.push(...result.items);}await snapshot();render();if(items.length)showResults({items});}finally{saveBusy=false;}}
async function copyObjectLink(type,id){await call('copyLink',{type,id});toast('Ссылка скопирована.');}
function mediaMenu(p,source){openDialog(p.kind==='album'?'Альбом':'Плейлист');$('dialogContent').append(make('p','dialog-note',p.title));$('dialogContent').append(expButton('Слушать',()=>{dismiss();return playMediaList(p,source);},'menu-action','play'),expButton('Перемешать',()=>{dismiss();return playMediaList(p,source,true);},'menu-action','mix'));if(source!=='local'&&!(db.vkLists||[]).some(x=>x.id===p.id||x.origin===p.id))$('dialogContent').append(expButton('Добавить в плейлисты VK',async()=>{const checked=await call('inspectList',{input:p.id});showListPreview(checked);},'menu-action','plus'));if(source!=='local')$('dialogContent').append(expButton('Скачать целиком в кеш',()=>{dismiss();return downloadMediaList(p,source);},'menu-action','down'),expButton('Копировать ссылку',()=>copyObjectLink('playlist',p.id),'menu-action','list'));}
function mediaCard(p,source='remote',small=false){if(!p.coverKey)p={...p,coverKey:(p.keys||[]).map(k=>db.rows[k]?.coverKey).find(Boolean)};const card=make('article',(small?'media-card media-card-small':'media-card playlist-card')+(source==='recommend'?' recommendation-card':''));card.tabIndex=0;card.setAttribute('role','link');card.setAttribute('aria-label',p.title);card.dataset.listId=p.id;card.dataset.source=source;card.onclick=e=>{if(!e.target.closest('button'))openMediaList(p,source);};card.onkeydown=e=>{if(e.key==='Enter'&&e.target===card){e.preventDefault();openMediaList(p,source);}};card.oncontextmenu=e=>{e.preventDefault();mediaMenu(p,source);};const art=make('div','media-art');art.append(coverArt(p.coverKey,p.kind==='album'?'disk':'list'));const actions=make('div','media-actions');for(const [label,symbol,random] of [['Перемешать','mix',true],['Слушать','play',false]]){const b=ib(label,symbol,e=>{e.stopPropagation();return action(()=>playMediaList(p,source,random))();});b.replaceChildren(icon(symbol));actions.append(b);}const more=ib('Действия с плейлистом','more',e=>{e.stopPropagation();mediaMenu(p,source);});actions.append(more);if(source!=='local')actions.append(ib(p.kind==='album'?'Скопировать ссылку на альбом':'Скопировать ссылку на плейлист','link',e=>{e.stopPropagation();return copyObjectLink(p.kind==='album'?'album':'playlist',p.id);},'copy-link-button'));art.append(actions);const date=labelRelease(p),meta=[source==='local'?'На ПК':'VK',date||counted(p.total??p.keys?.length??0)].filter(Boolean).join(' · ');const copy=make('div','media-copy');copy.append(make('strong','',p.title),make('small','muted',meta));if(p.artist)copy.append(make('small','muted',p.artist));card.append(art,copy);return card;}
function updateRailArrows(root){const shell=root.parentElement;if(!shell.classList.contains('media-rail-shell'))return;const max=root.scrollWidth-root.clientWidth;for(const b of shell.querySelectorAll('.rail-arrow')){b.hidden=max<3;b.disabled=b.classList.contains('left')?root.scrollLeft<2:root.scrollLeft>=max-2;}}
function mergeArtistAlbumPage(d,page){const albums=new Map((d.albums||[]).map(p=>[p.id,p]));for(const item of page.items||[])if(item?.id)albums.set(item.id,item);d.albums=[...albums.values()];d.albumsTotal=page.total;d.albumsNextOffset=page.nextOffset;d.albumsHasMore=page.hasMore===true;d.albumsError='';}
async function loadMoreArtistAlbums(d,{rerender=true}={}){if(!d||!fx.online)return false;if(d.albumsJob)return d.albumsJob;if(!d.albumsHasMore)return false;const account=db.profile?.id,epoch=fx.epoch,offset=Number.isSafeInteger(d.albumsNextOffset)?d.albumsNextOffset:0;const job=(async()=>{d.albumsLoading=true;try{const page=await call('artistAlbums',{id:d.id,offset});if(epoch!==fx.epoch||account!==db.profile?.id)throw Object.assign(Error('Аккаунт изменился.'),{code:'CANCELLED'});if(!Array.isArray(page?.items)||!Number.isSafeInteger(page.nextOffset)||page.nextOffset<offset||page.hasMore===true&&page.nextOffset===offset)throw Error('VK вернул некорректную страницу альбомов.');mergeArtistAlbumPage(d,page);if(rerender){await snapshot();if(epoch!==fx.epoch||account!==db.profile?.id)throw Object.assign(Error('Аккаунт изменился.'),{code:'CANCELLED'});render();renderFeatures();}return true;}catch(error){d.albumsError=error.message||'Не удалось загрузить альбомы.';throw error;}finally{d.albumsLoading=false;d.albumsJob=null;}})();d.albumsJob=job;return job;}
